import os, urllib.request, csv, io, collections
key=open(os.environ['GALAXY_API_KEY_FILE']).read().strip(); url=os.environ['GALAXY_URL']
hist='bbd44e69cb8906b52a0000cb84090a2d'; did='f9cad7b01a4721352f9968c061089339'
req=urllib.request.Request(f'{url}/api/histories/{hist}/contents/{did}/display', headers={'x-api-key':key})
txt=urllib.request.urlopen(req).read().decode(); rows=csv.reader(io.StringIO(txt), delimiter='\\t')
bins=collections.Counter(); counts=collections.Counter()
for r in rows:
    if len(r)<4 or r[0]"'!='"'chr22': continue
    start=int(r[1]); end=int(r[2]); depth=int(r[3]); b=100000
    bs=start//b; be=(end-1)//b
    for bi in range(bs, be+1):
        ov=min(end,(bi+1)*b)-max(start,bi*b)
        bins[bi]+=depth*ov; counts[bi]+=ov
# print contiguous segments where avg<0.5 and length >1 bin
low=[]; active=False
for i in range(0,509):
    avg=bins[i]/counts[i] if counts[i] else 0
    islow=avg<0.5
    if islow and not active:
        seg_start=i; active=True
    elif not islow and active:
        low.append((seg_start,i-1)); active=False
if active: low.append((seg_start,508))
print('low avg<0.5 segments:')
for s,e in low:
    print(f'{s*100000:9d}-{(e+1)*100000:9d} len={(e-s+1)*100000} bins {s}-{e}')
print('\\nlow avg<1.0 segments:')
low=[]; active=False
for i in range(0,509):
    avg=bins[i]/counts[i] if counts[i] else 0
    islow=avg<1.0
    if islow and not active:
        seg_start=i; active=True
    elif not islow and active:
        low.append((seg_start,i-1)); active=False
if active: low.append((seg_start,508))
for s,e in low:
    if (e-s+1)>=2:
        print(f'{s*100000:9d}-{(e+1)*100000:9d} len={(e-s+1)*100000} bins {s}-{e}')
PY"

