fn='/workspace/samtools_depth_chr22.tsv'
# find all maximal zero runs
runs=[]
start=None; prev=None; cur_start=None
with open(fn) as f:
    for line in f:
        p=line.split('\\t')
        pos=int(p[1]); dep=int(p[2])
        if dep==0:
            if cur_start is None:
                cur_start=pos
        else:
            if cur_start is not None:
                runs.append((cur_start, prev, prev-cur_start+1))
                cur_start=None
        prev=pos
if cur_start is not None:
    runs.append((cur_start,prev,prev-cur_start+1))
runs.sort(key=lambda x:-x[2])
for r in runs[:30]:
    print(r)
